import React, { useState, useEffect } from "react";
import {
  BrowserRouter as Router,
  Routes,
  Route,
  NavLink
} from "react-router-dom";

import { Toaster } from "react-hot-toast";

import HomePage from "./pages/HomePage";
import DashboardPage from "./pages/DashboardPage";
import SearchPage from "./pages/SearchPage";
import LawsPage from "./pages/LawsPage";
import DocumentsPage from "./pages/DocumentsPage";
import RAGSearchPage from "./pages/RAGSearchPage";

import Login from "./pages/Login";

import "./App.css";

export default function App() {

  const [lang, setLang] = useState("en");
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {

    const fn = () => setScrolled(window.scrollY > 20);

    window.addEventListener("scroll", fn);

    return () => window.removeEventListener("scroll", fn);

  }, []);

  return (

    <Router>

      <div className="bg-fx">
        <div className="bg-grid"/>
        <div className="orb o1"/>
        <div className="orb o2"/>
        <div className="orb o3"/>
      </div>

      <nav className={scrolled ? "scrolled" : ""}>

        <NavLink to="/" className="nlogo">

          <div className="nico">⚖</div>

          <div>
            <div className="nbrand">
              JusticeLens
            </div>

            <div className="nsub">
              AI Legal · RAG Powered
            </div>
          </div>

        </NavLink>

        <ul className="nlinks">

          {[
            ["/", "Home"],
            ["/dashboard", "Analytics"],
            ["/search", "Case Search"],
            ["/rag", "RAG Query"],
            ["/laws", "Laws"],
            ["/documents", "Documents"],
            ["/login", "Login"]
          ].map(([to, lbl]) => (

            <li key={to}>

              <NavLink
                to={to.trim()}
                end={to.trim() === "/"}
                className={({ isActive }) =>
                  isActive ? "act" : ""
                }
              >
                {lbl}
              </NavLink>

            </li>

          ))}

        </ul>

        <div className="nright">

          <i
            className="fas fa-globe"
            style={{
              color: "var(--gold)",
              fontSize: 14
            }}
          />

          <select
            value={lang}
            onChange={e => setLang(e.target.value)}
          >
            <option value="en">English</option>
            <option value="hi">हिंदी</option>
            <option value="pa">ਪੰਜਾਬੀ</option>
            <option value="ur">اردو</option>
          </select>

        </div>

      </nav>

      <main>

        <Routes>

          <Route
            path="/"
            element={<HomePage lang={lang} />}
          />

          <Route
            path="/dashboard"
            element={<DashboardPage />}
          />

          <Route
            path="/search"
            element={<SearchPage />}
          />

          <Route
            path="/rag"
            element={<RAGSearchPage />}
          />

          <Route
            path="/laws"
            element={<LawsPage />}
          />

          <Route
            path="/documents"
            element={<DocumentsPage />}
          />

          {/* LOGIN PAGE */}

          <Route
            path="/login"
            element={<Login />}
          />

        </Routes>

      </main>

      <footer>

        <div className="flogo">
          ⚖ JusticeLens AI v3
        </div>

        <p>
          RAG-Powered · TF-IDF Vector Search ·
          149 SC Judgments · Open Source
        </p>

        <p
          style={{
            marginTop: 8,
            fontSize: 11,
            opacity: .5
          }}
        >
          ⚠️ Educational purposes only.
          Consult a qualified lawyer
          for actual legal advice.
        </p>

      </footer>

      <Toaster
        position="bottom-right"
        toastOptions={{
          style: {
            background: "var(--panel)",
            border: "1px solid var(--gold)",
            color: "var(--gold)",
            fontFamily: "DM Sans"
          },
          duration: 3000
        }}
      />

    </Router>
  );
}
